'use strict';
/**
 * Actual networkless disposable MariaDB 10.11 integration test.
 * No production paths, no remote database, no real credentials.
 * Docker CLI is confined to an autogenerated name + immutable commands.
 */
const test=require('node:test');
const assert=require('node:assert/strict');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const {verifyExactBackupGrants}=require('../../honartik-u06-mysql-grants-v1.cjs');
const IMAGE='mariadb:10.11@sha256:7f22313fc130a377a44999965bcb0a08dd5b21e8502824c1b864f792f9bc66ab';
const ADMIN_SQL=[
 'CREATE DATABASE honartik_db',
 'CREATE TABLE honartik_db.u06_fixture(id INT PRIMARY KEY, amount BIGINT NOT NULL)',
 'INSERT INTO honartik_db.u06_fixture VALUES(1,100)',
 "CREATE USER 'honartik_universal_backup'@'127.0.0.1' IDENTIFIED BY 'fixture_only_never_production'",
 "GRANT SELECT, SHOW VIEW, TRIGGER, EVENT ON honartik_db.* TO 'honartik_universal_backup'@'127.0.0.1'"
].join(';')+';';
function docker(args,timeout=90000){
 return cp.execFileSync('docker',args,{
  encoding:'utf8',timeout,maxBuffer:512*1024,
  stdio:['ignore','pipe','pipe']}).trim();
}
test('isolated MariaDB real scoped account, deny DDL and extra grants', {timeout:180000}, async()=>{
 const name='u06-grants-'+crypto.randomBytes(5).toString('hex');
 let started=false;
 try{
  docker(['run','-d','--name',name,'--network','none','--memory','768m',
    '--pids-limit','128','--security-opt','no-new-privileges',
    '-e','MARIADB_ALLOW_EMPTY_ROOT_PASSWORD=1',IMAGE],120000);
  started=true;
  let ready=false;
  for(let i=0;i<50;i++){
   try{docker(['exec',name,'mariadb','-uroot','--skip-column-names','-e','SELECT 1'],8000);ready=true;break}
   catch{await new Promise(r=>setTimeout(r,800))}
  }
  assert.ok(ready,'disposable MariaDB readiness');
  docker(['exec',name,'mariadb','-uroot','-e',ADMIN_SQL],15000);
  const query=[
   'exec',name,'mariadb','-uroot','--batch','--skip-column-names','-e',
   "SHOW GRANTS FOR 'honartik_universal_backup'@'127.0.0.1'"
  ];
  const rows=docker(query,15000).split('\n').filter(Boolean);
  const matched=verifyExactBackupGrants(rows);
  assert.equal(matched.granted_scope_review_matches,true);
  assert.equal(matched.verified_by_trusted_root,false);
  assert.equal(matched.production_backup_enabled,false);
  assert.equal(rows.length,2);
  // Read-only account accesses only this throwaway table.
  const read=docker(['exec',name,'mariadb','-h127.0.0.1',
    '-uhonartik_universal_backup','-pfixture_only_never_production',
    '--skip-column-names','-e','SELECT COUNT(*),SUM(amount) FROM honartik_db.u06_fixture'],15000);
  assert.equal(read,'1\t100');
  // DDL refusal is real SQL authorization, not mocked permission.
  assert.throws(()=>docker(['exec',name,'mariadb','-h127.0.0.1',
    '-uhonartik_universal_backup','-pfixture_only_never_production',
    '-e','CREATE TABLE honartik_db.forbidden(id INT)'],15000));
  docker(['exec',name,'mariadb','-uroot','-e',
    "GRANT INSERT ON honartik_db.* TO 'honartik_universal_backup'@'127.0.0.1'"],15000);
  const widened=docker(query,15000).split('\n').filter(Boolean);
  assert.throws(()=>verifyExactBackupGrants(widened),/u06_mysql_grants_/);
  console.log('U06_REAL_MARIADB_NETWORKLESS_GRANTS=PASS');
  console.log('U06_NO_WRITE_GRANTS_PROVEN=PASS');
  console.log('U06_EXTRA_GRANTS_FAIL_CLOSED=PASS');
  console.log('U06_PRODUCTION_MUTATION=FALSE');
 }finally{
  if(started)try{docker(['rm','-f',name],60000)}catch{}
 }
});
